head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[ModelUtil > M > rejectWorkflow]<br/>현재 실행 중인 Workflow 를 중단 시킵니다.",
    "validation" : [
        "reject(선택) 파라미터로 실행을 중단 시키는 이유를 설정할 수 있어야 합니다. (기본값 'REJECT')",
        "reject(선택) 파라미터 생략 시 기본값 'REJECT' 로 동작해야 합니다.",
        "workflowId(선택) 파라미터로 중단시킬 Workflow 의 ID 를 설정할 수 있어야 합니다.",
        "workflowId(선택) 파라미터 생략 시 첫 번째 실행 중인 Workflow 를 중단해야 합니다.",
        "중단된 Workflow 객체를 반환해야 합니다.",
        "실행 중인 Workflow 가 없으면 null 을 반환해야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// workflow step 의 지연 function - rejectWorkflow 호출 시점 확보를 위한 2초 대기
scwin.wf_delay = function () {
    return new Promise(function (resolve) {
        setTimeout(function () {
            resolve();
        }, 2000);
    });
};

// workflow step 의 마지막 function - 정상 완료 시 호출 (reject 로 중단되면 호출되지 않음)
scwin.wf_function_last = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("[step] function_last - workflow 정상 완료 (reject 되지 않음)");
};



// workflow 전체 콜백
scwin.wf_resolveCallback = function (wObj) {
    wf_body_bottom.getObj("scwin").setReturnValue("[resolveCallback] workflow 정상 완료");
};

scwin.wf_rejectCallback = function (wObj) {
    var rejectReason = (wObj && wObj.promiseValue) ? wObj.promiseValue : "-";
    wf_body_bottom.getObj("scwin").setReturnValue("[rejectCallback] 수신 reject 사유 : '" + rejectReason + "'");
};



scwin.btn_rejectWorkflow_onclick = function () {
    var scenario = par_scenario.getValue();
    var reject = par_reject.getValue();
    var workflowId = par_workflowId.getValue();

    if (scenario === "1") {
        WebSquare.ModelUtil.executeWorkflow("wf_exam1");
        setTimeout(function () { WebSquare.ModelUtil.rejectWorkflow(reject); }, 500);
    } else if (scenario === "2") {
        WebSquare.ModelUtil.executeWorkflow("wf_exam1");
        setTimeout(function () { WebSquare.ModelUtil.rejectWorkflow("timeout", workflowId); }, 500);
    } else if (scenario === "3") {
        var result = WebSquare.ModelUtil.rejectWorkflow();
        wf_body_bottom.getObj("scwin").setReturnValue("WebSquare.ModelUtil.rejectWorkflow() → 반환값 : " + result + " (실행 중 workflow 없음)");
    } else if (scenario === "4") {
        WebSquare.ModelUtil.executeWorkflow("wf_exam1");
        setTimeout(function () { WebSquare.ModelUtil.rejectWorkflow(); }, 500);
    }
};
